LEVEL = 1
CFG = {1: {"a": ["b"], "b": []}, 2: {"a": ["b", "c"], "b": ["d"], "c": [], "d": []}, 3: {"a": ["b", "c"], "b": ["d", "e"], "c": ["e"], "d": [], "e": []}}
deps = CFG[LEVEL]
seen, stack = set(), ["a"]
while stack:
    n = stack.pop()
    for d in deps.get(n, []):
        if d not in seen: seen.add(d); stack.append(d)
print("upgrading 'a' affects:", sorted(seen), "| blast radius:", len(seen))

